mapper.update:
UPDATE car_goal
SET car_type_code = #{carTypeCode},
    selected_model_id = #{selectedModelId},
    selected_year = #{selectedYear},
    status = #{status},
    modified_date = NOW(),
    modified_nm = #{userId}
WHERE goal_id = #{goalId}
AND user_id = #{userId}
AND del_yn = 'N'

mapper.select:
SELECT *
FROM car_goal
WHERE goal_id = #{goalId}
AND user_id = #{userId}
AND del_yn = 'N'

SELECT *
FROM car_insurance
WHERE car_type_code = #{carTypeCode}
AND experience_bracket = #{experienceBracket}
AND del_yn = 'N'

SELECT

FROM car_goal g
LEFT JOIN car_model m ON g.selected_model_id = m.model_id
WHERE g.goal_id = #{goalId}
AND g.user_id = #{userId}
AND g.del_yn = 'N'
